import leetcode.medium.OnlineStockSpan;
import org.junit.Test;
import static org.junit.Assert.*;

public class OnlineStockSpanTest {

    // Test next method
    @Test
    public void nextSingleInvocationTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int result = stockSpan.next(100);
        assertEquals(1, result);
    }

    @Test
    public void nextMultipleInvocationsTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(100);
        int result = stockSpan.next(180);
        assertEquals(2, result);
    }

    @Test
    public void nextDecreasingPricesTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(100);
        int result = stockSpan.next(80);
        assertEquals(1, result);
    }

    // Test calculateSpans method
    @Test
    public void calculateSpansEmptyArrayTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] spans = stockSpan.calculateSpans(new int[]{});
        assertArrayEquals(new int[]{}, spans);
    }

    @Test
    public void calculateSpansSingleElementArrayTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] spans = stockSpan.calculateSpans(new int[]{100});
        assertArrayEquals(new int[]{1}, spans);
    }

    @Test
    public void calculateSpansMultipleElementArrayTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] spans = stockSpan.calculateSpans(new int[]{100, 180, 260, 310, 40, 535, 695});
        assertArrayEquals(new int[]{1, 2, 3, 4, 1, 2, 3}, spans);
    }
}
